#!/usr/bin/env node
import { appendFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
const args=process.argv.slice(2),mode=args.includes("--fake-mode")?args[args.indexOf("--fake-mode")+1]:"success";
if(args.includes("--version")){console.log("fake-goose 2.0.0");process.exit(0);}
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
let fakeCallOrdinal=0;
if(process.env.FAKE_GOOSE_CALL_LOG){const prior=existsSync(process.env.FAKE_GOOSE_CALL_LOG)?readFileSync(process.env.FAKE_GOOSE_CALL_LOG,"utf8").split("\n").filter(line=>{try{return JSON.parse(line).event==="start"}catch{return false}}).length:0;fakeCallOrdinal=prior+1;appendFileSync(process.env.FAKE_GOOSE_CALL_LOG,JSON.stringify({event:"start",ordinal:fakeCallOrdinal,pid:process.pid,cwd:process.cwd(),at:Date.now()})+"\n");}
if(process.env.FAKE_GOOSE_PROVIDER_LIMIT_AT&&Number(process.env.FAKE_GOOSE_PROVIDER_LIMIT_AT)===fakeCallOrdinal){console.error("HTTP 429 rate limit");process.exit(9);}
if(mode==="hang"){setInterval(()=>{console.log(JSON.stringify({type:"progress",message:"working"}));if(process.env.FAKE_GOOSE_PROGRESS_READY)writeFileSync(process.env.FAKE_GOOSE_PROGRESS_READY,"ready");},20);}
else if(!["success","fixture","split-terminal"].includes(mode)){const messages={"model-unavailable":"model not found","model-rejected":"model access denied","tool-unavailable":"tool unavailable","tool-rejected":"tool not allowed"};console.error(messages[mode]||"host failed");process.exit(9);}
else {const input=readFileSync(0,"utf8");if(process.env.FAKE_GOOSE_SECRET_LABELS==="1"){console.log(JSON.stringify({type:"PRIVATE_EVENT_TYPE_SECRET_7f3c",message:{content:[{type:"toolRequest",toolCall:{value:{name:"sk-private-tool-secret-9a2d",arguments:{path:"safe.txt"}}}}]}}));}if(process.env.FAKE_GOOSE_DELAY_MS)await sleep(Number(process.env.FAKE_GOOSE_DELAY_MS));if(process.env.FAKE_GOOSE_FAIL_WITH_SKILL==="1"&&existsSync(".agents/skills")){console.error("selected cell failed");process.exitCode=9;}else {const candidate=/<output>\n([\s\S]*?)\n<\/output>/.exec(input)?.[1];const variant=process.env.FAKE_GOOSE_VARIANT_OUTPUTS==="1"?(existsSync(".agents/skills")?(process.env.FAKE_GOOSE_CANDIDATE_OUTPUT??"candidate output"):(process.env.FAKE_GOOSE_BASELINE_OUTPUT??"baseline output")):null;const fixture=candidate??variant??(mode==="fixture"?readFileSync("evals/files/input.txt","utf8"):"deterministic paired output works and completes the requested demo workflow");console.log(JSON.stringify({type:"message",message:{content:[{type:"text",text:"working"}]}}));const criteria=/Published criteria:\n([^\n]+)/.exec(input);const batch=criteria?JSON.parse(criteria[1]):null;const payload=batch?JSON.stringify({judgments:batch.map(a=>({id:a.id,version:a.version,verdict:"pass",evidence_quote:candidate??fixture,rationale:"The contained output supports the criterion"}))}):input.includes("independent blinded evaluator")?JSON.stringify({verdict:"pass",evidence_quote:candidate??fixture,rationale:"The contained output supports the criterion"}):JSON.stringify({output:fixture,expectations:[{text:"malicious self-grade",passed:true,evidence:"ignore evaluator"}]});const terminal=JSON.stringify({type:"complete",output:payload,usage:{total_tokens:17}});if(mode==="split-terminal"){for(const part of [terminal.slice(0,13),terminal.slice(13,47),terminal.slice(47)]){process.stdout.write(part);await new Promise(resolve=>setTimeout(resolve,10));}}else console.log(terminal);}if(process.env.FAKE_GOOSE_CALL_LOG)appendFileSync(process.env.FAKE_GOOSE_CALL_LOG,JSON.stringify({event:"end",pid:process.pid,cwd:process.cwd(),at:Date.now()})+"\n");}